'use strict';
/*
 * collision_sweep.js
 * ---------------------------------------------------------------------------
 * STEP 3: systematic two-glider collision sweep -> a particle/product spectrum.
 *
 * Design decisions (each one avoids a mistake from the previous round):
 *
 *  1. ORIENTATIONS ARE GENERATED BY ROTATION, not hand-written RLE. I previously
 *     wrote an "LWSS" that decomposed into two components immediately. Rotating
 *     the verified glider cannot introduce that class of error, and the resulting
 *     velocity is predictable in advance (a rotation carries (1,1) to (-1,1),
 *     (-1,-1) or (1,-1)).
 *
 *  2. TRAJECTORY-FIRST DETECTION, not just component counting. Two gliders that
 *     pass through each other can leave the component count at 2 the whole time,
 *     so a "component count dropped" test would silently miss the interaction.
 *     Instead we record each object's velocity and terminal position, so
 *     annihilation / deflection / pass-through are distinguishable.
 *
 *  3. CONTROLS FIRST. A lone glider must be detected with period 4 and (1,1)
 *     before any sweep result is trusted.
 *
 * Output: for each (offset, heading) pair, the products of the collision,
 * classified as still life / oscillator / glider / debris / nothing.
 * ---------------------------------------------------------------------------
 */

const SIZE = 128;
const stride = SIZE;
const MAXSTEPS = 420;
const TRANSIENT = 300;       // run this long, then only stable things remain

function wrapCell(x, y) { return ((y % SIZE) + SIZE) % SIZE * stride + (((x % SIZE) + SIZE) % SIZE); }

function step(set) {
  const counts = new Map();
  for (const k of set) {
    const x = k % stride, y = (k - x) / stride;
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        const nk = wrapCell(x + dx, y + dy);
        counts.set(nk, (counts.get(nk) || 0) + 1);
      }
    }
  }
  const out = new Set();
  for (const [k, c] of counts) if (c === 3 || (c === 2 && set.has(k))) out.add(k);
  return out;
}

function components(set) {
  const seen = new Set(), comps = [], Q = [];
  for (const start of set) {
    if (seen.has(start)) continue;
    Q.length = 0; Q.push(start); seen.add(start);
    const cells = [];
    while (Q.length) {
      const k = Q.pop(); cells.push(k);
      const x = k % stride, y = (k - x) / stride;
      for (let dy = -1; dy <= 1; dy++) {
        for (let dx = -1; dx <= 1; dx++) {
          if (dx === 0 && dy === 0) continue;
          const nk = wrapCell(x + dx, y + dy);
          if (set.has(nk) && !seen.has(nk)) { seen.add(nk); Q.push(nk); }
        }
      }
    }
    comps.push(cells);
  }
  return comps;
}

function canon(cells) {
  let minx = Infinity, miny = Infinity, maxx = -Infinity, maxy = -Infinity, sx = 0, sy = 0;
  for (const k of cells) {
    const x = k % stride, y = (k - x) / stride;
    if (x < minx) minx = x; if (x > maxx) maxx = x;
    if (y < miny) miny = y; if (y > maxy) maxy = y;
    sx += x; sy += y;
  }
  const w = maxx - minx + 1, h = maxy - miny + 1;
  const g = [];
  for (let r = 0; r < h; r++) g.push(new Array(w).fill('.'));
  for (const k of cells) {
    const x = k % stride, y = (k - x) / stride;
    g[y - miny][x - minx] = 'o';
  }
  const rows = g.map(r => r.join(''));
  return { w, h, n: cells.length, sx, sy, cx: sx / cells.length, cy: sy / cells.length, id: `${w}x${h}:` + rows.join('/'), rows };
}

// ---- glider constructed by rotation of the VERIFIED phase-0 glider
const GLIDER0 = [[1, 0], [2, 1], [0, 2], [1, 2], [2, 2]];
// rotate (dx,dy) by 90 degrees: (dx,dy) -> (-dy,dx)
function rotCells(turns) {
  return GLIDER0.map(([dx, dy]) => {
    let a = dx, b = dy;
    for (let i = 0; i < turns; i++) { const na = -b, nb = a; a = na; b = nb; }
    return [a, b];
  });
}
// headings in turns: 0 -> (1,1), 1 -> (-1,1), 2 -> (-1,-1), 3 -> (1,-1)
const HEAD_VEL = [[1, 1], [-1, 1], [-1, -1], [1, -1]];

function gliderAt(x, y, turns) {
  const s = new Set();
  for (const [dx, dy] of rotCells(turns)) s.add(wrapCell(x + dx, y + dy));
  return s;
}
function union(...sets) { const o = new Set(); for (const s of sets) for (const k of s) o.add(k); return o; }

// ---- controls
function trackSingle(init, steps) {
  let set = init;
  const frames = [];
  for (let t = 0; t <= steps; t++) {
    const comps = components(set);
    if (comps.length !== 1) return { ok: false, reason: `expected 1 component, got ${comps.length}`, t };
    frames.push(canon(comps[0]));
    set = step(set);
  }
  for (let p = 1; p <= 12; p++) {
    let ok = true, base = null;
    for (let t = 0; t + p < frames.length; t++) {
      if (frames[t].id !== frames[t + p].id) { ok = false; break; }
      let dsx = (frames[t + p].sx - frames[t].sx) / frames[t].n;
      let dsy = (frames[t + p].sy - frames[t].sy) / frames[t].n;
      if (Math.abs(dsx) > SIZE / 2) dsx -= Math.sign(dsx) * SIZE;
      if (Math.abs(dsy) > SIZE / 2) dsy -= Math.sign(dsy) * SIZE;
      const d = [Math.round(dsx), Math.round(dsy)];
      if (base === null) base = d;
      else if (d[0] !== base[0] || d[1] !== base[1]) { ok = false; break; }
    }
    if (ok && base && (base[0] || base[1])) return { ok: true, p, vx: base[0], vy: base[1], id: frames[0].id };
  }
  return { ok: false, reason: 'no periodic recurrence with constant drift' };
}

/*
 * AUTO-CLASSIFIER for unknown terminal components.
 * Rather than hand-identifying patterns (I got an "LWSS" wrong that way), take the
 * shape out of context, evolve it in isolation, and measure:
 *   - does it survive?
 *   - smallest period p with shape recurrence
 *   - net displacement per period
 * => still life / oscillator / MOVER (possible new particle) / debris.
 */
const classCache = new Map();
function classifyShape(id) {
  if (classCache.has(id)) return classCache.get(id);
  const parts = id.split(':');
  const dimStr = parts[0] || '';
  const rowsStr = parts.slice(1).join(':') || '';
  const rows = rowsStr.split('/').filter(r => r.length);
  if (!rows.length) {
    const r = { kind: 'MALFORMED ID (ignored)', p: 0 };
    classCache.set(id, r); return r;
  }
  // A component that spans half the torus is wrapped around the boundary; its
  // bounding box and centroid are meaningless, so refuse to classify it.
  const w = rows[0].length, h = rows.length;
  if (/^\d+x\d+$/.test(dimStr)) {
    const [ww, hh] = dimStr.split('x').map(Number);
    if (ww > SIZE / 2 || hh > SIZE / 2) {
      const r = { kind: 'WRAPPED ACROSS BOUNDARY (unreliable)', p: 0 };
      classCache.set(id, r); return r;
    }
  }
  let set = new Set();
  for (let y = 0; y < rows.length; y++) {
    for (let x = 0; x < rows[y].length; x++) {
      if (rows[y][x] === 'o') set.add(wrapCell(200 + x, 200 + y));   // far from wrap
    }
  }
  const hist = [];
  let s = set;
  for (let t = 0; t < 80; t++) {
    const cs = components(s).map(c => canon(c));
    hist.push(cs);
    if (s.size === 0) break;
    s = step(s);
  }
  if (s.size === 0) {
    const r = { kind: 'DEBRIS (dies out)', p: 0 };
    classCache.set(id, r); return r;
  }
  const sig = (cs) => cs.map(c => c.id).sort().join('|');
  const cent = (cs) => cs.map(c => [c.n, Math.round(c.cx * 1000), Math.round(c.cy * 1000)]).sort().join(';');
  for (let p = 1; p <= 15; p++) {
    let ok = true;
    for (let t = 40; t + p < hist.length; t++) {
      if (sig(hist[t]) !== sig(hist[t + p])) { ok = false; break; }
    }
    if (!ok) continue;
    const moved = cent(hist[40]) !== cent(hist[40 + p]);
    const r = moved
      ? { kind: 'MOVER (periodic, translates) <<-- possible particle', p, v: cent(hist[40 + p]) }
      : { kind: p === 1 ? 'still life' : `oscillator (period ${p})`, p };
    classCache.set(id, r); return r;
  }
  const r = { kind: 'UNSETTLED / chaotic within 80 gens', p: 0 };
  classCache.set(id, r); return r;
}

console.log('=== controls: each of the four rotated gliders must be a (1,1)-class mover ===');
const headOk = [];
for (let turns = 0; turns < 4; turns++) {
  const t = trackSingle(gliderAt(20, 20, turns), 60);
  const expect = HEAD_VEL[turns];
  const got = t.ok ? [t.vx, t.vy] : null;
  const pass = t.ok && got[0] === expect[0] && got[1] === expect[1];
  headOk.push(pass);
  console.log(`  turns=${turns} expect (${expect}) got ${got ? `(${got})` : 'FAIL: ' + t.reason}  ${pass ? 'PASS' : '*** FAIL ***'}`);
}
if (!headOk.every(Boolean)) {
  console.log('\n*** a control failed -- sweep results would be meaningless, stopping ***');
  process.exit(1);
}
console.log('');

// ---- classification of terminal objects
const KNOWN = new Map();
function reg(rows, name) { KNOWN.set(`${rows[0].length}x${rows.length}:` + rows.join('/'), name); }
reg(['oo', 'oo'], 'block (still life)');
reg(['.oo.', 'o..o', '.oo.'], 'loaf (still life)');
reg(['.o.', 'o.o', 'o.o', '.o.'], 'ship (still life)');
reg(['.oo', 'o.o', '.oo'], 'beehive (still life)');
reg(['.o.', '..o', 'ooo'], 'glider phase 0');
reg(['.o.', '.o.', '.o.'], 'blinker');
reg(['ooo'], 'blinker (horizontal)');
reg(['ooo', 'o.o', 'ooo'], 'ring / toad-ish (verify)');
reg(['.o.', 'o.o', '.o.'], '?? 3x3 (verify)');
reg(['..o', '.o.', 'o..'], '?? diagonal 3x3 (verify)');
reg(['o..', '.o.', '..o'], '?? diagonal 3x3 (verify)');
reg(['.o.', 'o..', 'ooo'], '?? (verify)');
reg(['o.o', '.o.', 'o.o'], '?? (verify)');
reg(['oo.', 'o..', 'o..'], '?? (verify)');
reg(['..oo', 'o...', 'o...', '.o..'], '?? (verify)');

const products = new Map();     // productId -> {count, examples}

/*
 * TERMINAL STATE DETECTION.
 * The first sweep classified whatever was on the board at a fixed step 300, so
 * oscillators still in mid-cycle were reported as "UNKNOWN 1x3 (n=3)" (19 times)
 * -- those are blinker phases, not new objects. A product spectrum is only
 * meaningful if it is read from a SETTLED state.
 *
 * A state is called settled if the multiset of component shapes repeats with some
 * period p (p=1 -> still life, p>1 -> oscillator) AND no component is executing a
 * net translation. We detect this by hashing the shape multiset each step and
 * looking for a repeat within a lookback window.
 */
function multisetHash(set) {
  const ids = components(set).map(c => canon(c).id).sort();
  let h = 2166136261;
  for (const id of ids) {
    for (let i = 0; i < id.length; i++) h = Math.imul(h ^ id.charCodeAt(i), 16777619);
    h = Math.imul(h ^ 0x2c1b3c6d, 16777619);
  }
  return (h >>> 0) + ':' + ids.length;
}

function settleInfo(init) {
  let set = init;
  const hashes = [];
  const positions = [];       // array of sorted [id,cx,cy] per step
  for (let t = 0; t <= MAXSTEPS; t++) {
    hashes.push(multisetHash(set));
    const cs = components(set).map(c => canon(c)).sort((a, b) => a.id < b.id ? -1 : 1);
    positions.push(cs.map(c => [c.id, Math.round(c.cx * 100), Math.round(c.cy * 100)]));
    if (t === MAXSTEPS) break;
    set = step(set);
  }
  // find a period p such that the shape multiset repeats and positions are
  // either identical (still) or uniformly translated (oscillator)
  for (let p = 1; p <= 30; p++) {
    const T = MAXSTEPS;
    if (T - p < 0) break;
    let ok = true;
    for (let t = T - p; t <= T - 1; t++) {
      if (hashes[t] !== hashes[t + p]) { ok = false; break; }
    }
    if (!ok) continue;
    // check it has been repeating for a while (not a coincidence)
    let repeats = 0;
    for (let t = T - p; t - p >= 0; t -= p) {
      if (hashes[t - p] === hashes[t]) repeats++; else break;
    }
    if (repeats < 2) continue;
    const moved = JSON.stringify(positions[T]) !== JSON.stringify(positions[T - p]);
    return { settled: true, period: p, still: !moved, final: set, hash: hashes[T], positions: positions[T] };
  }
  return { settled: false, final: set, hash: hashes[MAXSTEPS], positions: positions[MAXSTEPS] };
}

function sweep(offsetX, offsetY, headingTurns) {
  const A = gliderAt(30, 30, 0);
  const B = gliderAt(30 + offsetX, 30 + offsetY, headingTurns);
  if (A.size + B.size !== union(A, B).size) return { overlap: true };
  const init = union(A, B);
  let set = init;
  const masses = [];
  let merged = -1, prevComps = -1;
  for (let t = 0; t <= MAXSTEPS; t++) {
    const comps = components(set);
    masses.push(set.size);
    if (comps.length < prevComps && prevComps >= 2 && merged < 0) merged = t;
    prevComps = comps.length;
    if (t === MAXSTEPS) break;
    set = step(set);
  }
  const initMass = masses[0];
  const interacted = merged >= 0 || masses.some(m => m !== initMass);
  return { init, masses, initMass, interacted, merged };
}

// ---- main sweep
const OFFS = [0, 1, 2, 3, 4, 6, 8];
const results = [];
console.log('=== two-glider collision sweep ===');
console.log('A: glider at (30,30) heading (+1,+1)');
console.log('B: glider at (30+ox, 30+oy) heading by turns');
console.log('steps: %d (transient) then classify the terminal configuration\n', TRANSIENT);

for (const heading of [1, 2, 3]) {
  for (const ox of OFFS) {
    for (const oy of OFFS) {
      const r = sweep(ox, oy, heading);
      if (r.overlap) continue;
      const si = settleInfo(r.init);
      const final = components(si.final).map(c => canon(c));
      const objs = final.map(f => ({
        id: f.id, w: f.w, h: f.h, n: f.n,
        name: KNOWN.get(f.id) || null,
      }));
      const key = objs.map(o => o.name || `UNKNOWN ${o.w}x${o.h}(n=${o.n})`).sort().join(' + ') || 'NOTHING';
      results.push({
        heading, ox, oy, interacted: r.interacted, nFinal: objs.length, key, objs,
        settled: si.settled, period: si.period, still: si.still,
      });
    }
  }
}

// ---- interaction matrix
console.log('=== interaction map (I = interacted, . = passed through) ===');
for (const heading of [1, 2, 3]) {
  console.log(`heading turns=${heading} velocity (${HEAD_VEL[heading]})`);
  console.log('      oy\\ox ' + OFFS.map(o => String(o).padStart(3)).join(''));
  for (const oy of OFFS) {
    let line = '      ' + String(oy).padStart(5) + ' ';
    for (const ox of OFFS) {
      const r = results.find(q => q.heading === heading && q.ox === ox && q.oy === oy);
      line += (r ? (r.interacted ? '  I' : '  .') : '  x');
    }
    console.log(line);
  }
}

// ---- (superseded) raw product dump removed; see the SETTLED spectrum below.
const interacting = results.filter(r => r.interacted);
console.log(`interacting configurations: ${interacting.length} of ${results.length}`);

// ---- unknown products, auto-classified
console.log('\n=== unknown terminal objects, AUTO-CLASSIFIED in isolation ===');
const unk = new Map();
for (const r of interacting) for (const o of r.objs) if (!o.name) unk.set(o.id, (unk.get(o.id) || 0) + 1);
const unkList = [...unk.entries()].sort((a, b) => b[1] - a[1]);
console.log(`distinct unknown shapes: ${unkList.length}`);
for (const [id, count] of unkList) {
  const cls = classifyShape(id);
  const parts = id.split(':');
  const dims = parts[0];
  const rowArr = parts.slice(1).join(':').split('/');
  const compact = rowArr.length <= 4 && rowArr[0] && rowArr[0].length <= 6;
  console.log(`  x${String(count).padStart(2)}  ${dims.padEnd(9)}  ${cls.kind}${cls.p ? `  (p=${cls.p})` : ''}`);
  if (compact) for (const row of rowArr) console.log(`          ${row}`);
}

// ---- the real spectrum
console.log('\n=== SETTLED product spectrum ===');
const settledOnes = interacting.filter(r => r.settled);
const unsettled = interacting.filter(r => !r.settled);
console.log(`interacting: ${interacting.length}   settled: ${settledOnes.length}   NOT settled: ${unsettled.length}`);
if (unsettled.length) {
  console.log(`(the ${unsettled.length} unsettled ones are NOT reliable products; they are`);
  console.log(` still churning after ${MAXSTEPS} steps -- listed for transparency)`);
  for (const r of unsettled) console.log(`   h${r.heading}(${r.ox},${r.oy})`);
}

const agg = new Map();
for (const r of settledOnes) {
  const kinds = r.objs.map(o => o.name ? 'STABLE' : classifyShape(o.id).kind);
  const anyMover = kinds.some(k => /MOVER/.test(k));
  const anyBad = kinds.some(k => /WRAPPED|UNSETTLED|MALFORMED/.test(k));
  const allStable = kinds.every(k => /STABLE|still life|oscillator/.test(k));
  const tag = r.objs.length === 0 ? 'total annihilation (nothing survives)'
    : anyMover ? 'CONTAINS A MOVER'
      : anyBad ? 'contains an unclassifiable component'
        : allStable ? 'all stable (still life / oscillator)'
          : 'mixed';
  const key = `${r.objs.length} obj: ${tag}`;
  agg.set(key, (agg.get(key) || 0) + 1);
}
console.log('');
for (const [k, v] of [...agg.entries()].sort((a, b) => b[1] - a[1])) {
  console.log(`  ${String(v).padStart(3)}x  ${k}`);
}

// ---- the clean product list: which distinct objects ever survive
console.log('\n=== distinct surviving objects (settled configurations only) ===');
const surv = new Map();
for (const r of settledOnes) for (const o of r.objs) {
  const nm = o.name || `UNKNOWN ${o.w}x${o.h}: ${classifyShape(o.id).kind}`;
  surv.set(nm, (surv.get(nm) || 0) + 1);
}
for (const [k, v] of [...surv.entries()].sort((a, b) => b[1] - a[1])) {
  console.log(`  ${String(v).padStart(4)}x  ${k}`);
}
